package com.voicetxt.reader;

import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.*;
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.atomic.*;

public class VoicePackageImportTest extends Instrumentation {
    void check(boolean value,String message){if(!value)throw new AssertionError(message);}
    int descriptions(android.view.View view,String text){int count=text.contentEquals(view.getContentDescription()==null?"":view.getContentDescription())?1:0;if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++)count+=descriptions(group.getChildAt(i),text);}return count;}
    void ui(Runnable task){AtomicReference<Throwable> failure=new AtomicReference<>();runOnMainSync(()->{try{task.run();}catch(Throwable error){failure.set(error);}});if(failure.get()!=null)throw new AssertionError(failure.get());}
    void await(java.util.function.BooleanSupplier condition,String message,long timeout)throws Exception{long until=SystemClock.elapsedRealtime()+timeout;while(SystemClock.elapsedRealtime()<until){AtomicBoolean ready=new AtomicBoolean();ui(()->ready.set(condition.getAsBoolean()));if(ready.get())return;Thread.sleep(100);}throw new AssertionError(message);}
    void imported(VoicePackages packages,String phase,String error)throws Exception{await(()->!packages.busy,"Import did not finish: "+packages.phase,120000);check(packages.phase.equals(phase),"Expected "+phase+" got "+packages.phase+" / "+packages.error);check(packages.error.equals(error),"Expected error "+error+" got "+packages.error);}
    void restore(SharedPreferences prefs,Map<String,?> saved){SharedPreferences.Editor edit=prefs.edit().clear();for(Map.Entry<String,?> entry:saved.entrySet()){Object value=entry.getValue();String key=entry.getKey();if(value instanceof String)edit.putString(key,(String)value);else if(value instanceof Integer)edit.putInt(key,(Integer)value);else if(value instanceof Long)edit.putLong(key,(Long)value);else if(value instanceof Float)edit.putFloat(key,(Float)value);else if(value instanceof Boolean)edit.putBoolean(key,(Boolean)value);}edit.commit();}
    public void onCreate(Bundle state){super.onCreate(state);start();}
    public void onStart(){Bundle result=new Bundle();Context context=getTargetContext();SharedPreferences prefs=context.getSharedPreferences("reading_settings",0);Map<String,?> saved=new HashMap<>(prefs.getAll());OfflineVoicesActivity manager=null;MainActivity reader=null;VoicePackages packages=VoicePackages.get(context);HashSet<String> before=new HashSet<>(packages.models.keySet());VoicePackages.Connections originalNetwork=packages.connections;File fixtures=new File(context.getExternalFilesDir(null),"voice-import-qa");boolean passed=false;
        try{
            check(!context.getSystemService(KeyguardManager.class).isKeyguardLocked(),"Unlock phone for voice import test");check(!packages.busy,"User import already running");check(new File(fixtures,"qa-chinese.zip").isFile(),"Fixtures missing");
            manager=(OfflineVoicesActivity)startActivitySync(new Intent(context,OfflineVoicesActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final OfflineVoicesActivity m=manager;
            await(()->m.system!=null&&m.system.initialized,"Manager engine initialization",30000);
            ui(()->{check(m.headers.size()==15,"Language groups changed");for(String language:VoiceLanguages.CODES){m.expanded=language;m.render();check(descriptions(m.root,m.getString(R.string.vp_import))==1,"Import entry duplicated in "+language);check(descriptions(m.root,m.getString(R.string.vp_address))==1,"URL entry duplicated in "+language);check(descriptions(m.body.getChildAt(0),m.getString(R.string.vp_import))==1,"Import entry not in top card");}m.expanded="zh";m.render();check(m.items("en").stream().noneMatch(item->item.pack!=null&&!item.pack.supports("en")),"Wrong initial language");});
            packages.importUri("en",Uri.fromFile(new File(fixtures,"qa-chinese.zip")));imported(packages,"failed","language");check(packages.models.size()==before.size(),"Mismatched package was published");
            for(String fixture:new String[]{"qa-traversal.zip","qa-symlink.tar","qa-unknown-language.zip","qa-incomplete.zip","qa-bad-native.zip"}){
                packages.importUri("",Uri.fromFile(new File(fixtures,fixture)));await(()->!packages.busy,"Invalid fixture hung: "+fixture,120000);check(packages.phase.equals("failed"),"Bad fixture accepted: "+fixture);check(packages.models.size()==before.size(),"Invalid model published");check(!new File(context.getFilesDir(),"voice-test-escape.txt").exists(),"Archive escaped destination");result.putString(fixture,packages.error);
            }
            // A native graph rejection (or validator process death) must leave the visible app alive.
            ui(()->check(!m.isDestroyed()&&!m.isFinishing(),"Validator failure killed management activity"));
            ui(()->{m.importLanguage="en";Intent selected=new Intent().setData(Uri.fromFile(new File(fixtures,"qa-chinese.tar.bz2")));m.onActivityResult(702,Activity.RESULT_OK,selected);});
            imported(packages,"done","");String id=packages.lastInstalled;VoiceModel pack=packages.models.get(id);check(pack!=null&&pack.supports("zh")&&!pack.supports("en"),"Model languages wrong");check(packages.list("zh").contains(pack)&&packages.list("zh-Hant").contains(pack),"Detected language variants not grouped");check(packages.models.size()==before.size()+1,"Multilingual package duplicated on disk");check(pack.speakers>10&&pack.sampleRate==8000,"Native probe not completed");check(VoiceModel.read(pack.directory).id.equals(id),"Installed model metadata did not persist");
            await(()->m.voiceRows.values().stream().anyMatch(row->row.item.pack!=null&&row.item.pack.id.equals(id)),"Imported model missing from language UI",5000);
            final OfflineVoicesActivity.Item[] selected={null};ui(()->{for(OfflineVoicesActivity.Item item:m.items("zh"))if(item.pack!=null&&item.pack.id.equals(id))selected[0]=item;check(selected[0]!=null,"Imported row missing");m.select(selected[0]);check(m.previewKey.isEmpty()&&!m.previewStarted,"Selecting package started preview");check(m.selectedKey("zh").equals(selected[0].key),"Package selection not saved");m.preview(selected[0]);});
            await(()->m.previewStarted,"Actual imported voice preview did not start",45000);ui(()->{m.preview(selected[0]);check(m.previewKey.isEmpty(),"Imported preview did not stop");});
            await(()->!packages.leases.containsKey(id),"Preview did not release model lease",20000);
            packages.importUri("",Uri.fromFile(new File(fixtures,"qa-chinese.tar.bz2")));imported(packages,"failed","duplicate");
            // Exercise the URL downloader with deterministic HTTPS responses, redirect handling and real payload bytes.
            File zip=new File(fixtures,"qa-chinese.zip");AtomicInteger requests=new AtomicInteger();packages.connections=url->new HttpURLConnection(url){public void disconnect(){}public boolean usingProxy(){return false;}public void connect(){}public int getResponseCode(){requests.incrementAndGet();return url.getPath().equals("/start")?302:200;}public String getHeaderField(String name){return name.equals("Location")?"https://voice-fixture.invalid/package.zip":null;}public long getContentLengthLong(){return zip.length();}public InputStream getInputStream()throws IOException{return new FileInputStream(zip);}};
            packages.download("","https://voice-fixture.invalid/start");imported(packages,"done","");String secondId=packages.lastInstalled;check(requests.get()==2,"HTTPS redirect not followed");check(packages.models.containsKey(secondId)&&packages.models.get(secondId).supports("zh"),"URL package not auto-classified");
            try{VoicePackages.address("http://voice-fixture.invalid/file.zip");throw new AssertionError("Plain HTTP accepted");}catch(IOException expected){}
            packages.connections=url->new HttpURLConnection(url){public void disconnect(){}public boolean usingProxy(){return false;}public void connect(){}public int getResponseCode(){return 302;}public String getHeaderField(String key){return "http://voice-fixture.invalid/unsafe";}};
            packages.download("zh","https://voice-fixture.invalid/start");imported(packages,"failed","url");
            packages.connections=originalNetwork;
            // Cancellation removes staging data and never publishes partial packages.
            check(packages.begin("zh"),"Cannot start cancellation fixture");packages.worker.execute(()->packages.runImport("zh","cancel.zip",()->new FilterInputStream(new FileInputStream(zip)){public int read(byte[] bytes,int offset,int length)throws IOException{try{Thread.sleep(50);}catch(InterruptedException error){throw new IOException("cancelled");}return super.read(bytes,offset,Math.min(length,2048));}},null));
            await(()->packages.transferred>0,"Cancel fixture not copying",5000);packages.cancel();imported(packages,"failed","cancelled");check(packages.staging.list().length==0,"Cancelled import left partial data");
            // Read an actual sentence using the imported speaker, then prove deletion is blocked while leased.
            ui(()->{prefs.edit().putString("readingLanguage","").putString("systemVoiceKey",pack.key(10)).putString("chineseVoiceKey",pack.key(10)).apply();m.finish();});manager=null;
            reader=(MainActivity)startActivitySync(new Intent(context,MainActivity.class).putExtra("book_id","voice_package_qa").putExtra("book_name","导入语音包验证").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final MainActivity a=reader;
            await(()->a.system!=null&&a.system.initialized,"Reader engines not ready",30000);
            ui(()->{a.text="第一章 测试\n微风轻轻吹过山间，书页慢慢翻动。我们沿着小路前行，欣赏四周的风景。";a.chapters=MainActivity.parse(a.text);a.position=0;a.readingLanguage="";a.systemVoiceKey=pack.key(10);a.loopPlayback=false;a.rate=1;a.showPosition(true);check(a.ensureReadingVoice()&&!a.usesSystem(),"Reader did not accept imported voice");a.startReading();});
            await(()->a.playing&&a.latestHighlightEnd>0&&a.latestStatus.startsWith(a.getString(R.string.vp_reading)),"Imported voice did not read/highlight text",45000);
            packages.delete(id);imported(packages,"failed","in_use");check(packages.models.containsKey(id),"Playing model deleted");
            ui(()->{a.stop();a.chooseVoice();check(a.voicePicker.host.items().stream().anyMatch(item->item.key.equals(pack.key(10))),"Imported voice missing from reader picker");});
            Thread.sleep(500);android.graphics.Bitmap screenshot=getUiAutomation().takeScreenshot();if(screenshot!=null){try(FileOutputStream out=new FileOutputStream(new File(context.getExternalFilesDir(null),"voice-package-reader.png"))){screenshot.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}screenshot.recycle();}
            ui(()->{a.voicePicker.dismiss();a.finish();});reader=null;await(()->!packages.leases.containsKey(id),"Reader lease not released",20000);
            manager=(OfflineVoicesActivity)startActivitySync(new Intent(context,OfflineVoicesActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final OfflineVoicesActivity finalManager=manager;await(()->finalManager.system!=null&&finalManager.system.initialized,"Final UI not ready",30000);ui(()->{finalManager.expanded="zh";finalManager.render();});Thread.sleep(500);
            screenshot=getUiAutomation().takeScreenshot();if(screenshot!=null){try(FileOutputStream out=new FileOutputStream(new File(context.getExternalFilesDir(null),"voice-package-manager.png"))){screenshot.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}screenshot.recycle();}
            packages.delete(id);imported(packages,"deleted","");check(!pack.directory.exists()&&packages.resolve(pack.key(10),"zh")==null,"Deleted model still available");
            result.putString("result","PASS: 15 groups; file-result import; zip/tar.bz2 extraction; model metadata language validation; mismatch/unknown/incomplete/traversal/symlink/invalid native graph rejection; separate-process validation leaves app alive; atomic publish and metadata persistence; silent selection; actual imported preview and stop; multi-speaker reader playback/highlight; unified picker; deterministic HTTPS redirect download; HTTP downgrade rejection; duplicate/cancel cleanup; in-use deletion blocked; app-owned deletion");passed=true;
        }catch(Throwable error){result.putString("error",android.util.Log.getStackTraceString(error));result.putString("packageState",packages.phase+" / "+packages.error);}
        finally{packages.connections=originalNetwork;if(reader!=null){final MainActivity a=reader;ui(()->{a.stop();a.finish();});}if(manager!=null){final OfflineVoicesActivity m=manager;ui(m::finish);}waitForIdleSync();try{long end=SystemClock.elapsedRealtime()+20000;while((packages.busy||!packages.leases.isEmpty())&&SystemClock.elapsedRealtime()<end)Thread.sleep(100);for(String id:new ArrayList<>(packages.models.keySet()))if(!before.contains(id)){packages.delete(id);long until=SystemClock.elapsedRealtime()+15000;while(packages.busy&&SystemClock.elapsedRealtime()<until)Thread.sleep(100);}}catch(Exception ignored){}restore(prefs,saved);packages.phase="";packages.error="";context.getSharedPreferences("reader_voice_package_qa",0).edit().clear().commit();new File(context.getFilesDir(),"book_voice_package_qa.txt.position").delete();}
        finish(passed?-1:0,result);
    }
}
